<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { api } from '../api/client'
import type { NodeItem, Task, WorkLog } from '../api/types'
import { useAuthStore } from '../stores/auth'
const route=useRoute(); const router=useRouter(); const auth=useAuthStore(); const id=Number(route.params.id); const node=ref<NodeItem>(); const workDialog=ref(false); const taskDialog=ref(false); const selected=ref<Task>();
const taskForm=reactive({name:'',description:'',dueDate:'',estimateDays:1}); const workForm=reactive({workDate:new Date().toISOString().slice(0,10),days:0.5,note:''})
const readOnly=computed(()=>auth.isViewer)
async function load(){try{node.value=await api<NodeItem>('GET',`/nodes/${id}`)}catch(e){ElMessage.error((e as Error).message)}}
async function setStatus(status:string){try{await api('POST',`/nodes/${id}/status`,{status});await load()}catch(e){ElMessage.error((e as Error).message)}}
async function setProgress(value:number){try{await api('PUT',`/nodes/${id}/progress`,{progress:value});await load()}catch(e){ElMessage.error((e as Error).message)}}
async function block(){try{await api('POST',`/nodes/${id}/block`,{reason:'进展受阻，待负责人补充处理'});await load()}catch(e){ElMessage.error((e as Error).message)}}
async function unblock(){try{await api('POST',`/nodes/${id}/unblock`);await load()}catch(e){ElMessage.error((e as Error).message)}}
async function createTask(){try{await api('POST',`/nodes/${id}/tasks`,taskForm);taskDialog.value=false;await load()}catch(e){ElMessage.error((e as Error).message)}}
async function addWork(){if(!selected.value)return;try{await api<WorkLog>('POST',`/tasks/${selected.value.id}/work-logs`,workForm);workDialog.value=false;await load()}catch(e){ElMessage.error((e as Error).message)}}
function onProgress(value: unknown) { void setProgress(Number(value)) }
function openWork(task:Task){selected.value=task;workDialog.value=true} onMounted(load)
</script>
<template><div><header class="page-head"><div><el-breadcrumb separator="/"><el-breadcrumb-item :to="`/projects/${node?.projectId}/timeline`">时间线</el-breadcrumb-item><el-breadcrumb-item>{{node?.name}}</el-breadcrumb-item></el-breadcrumb><h1 style="margin-top:14px">{{node?.name}}</h1><p>{{node?.moduleName}} · {{node?.ownerName}} · {{node?.planStart}} 至 {{node?.planEnd}}</p></div><el-button @click="router.push(`/nodes/${id}/kanban`)">任务看板</el-button></header>
<section class="surface" style="margin-bottom:18px"><div style="display:grid;grid-template-columns:160px 1fr auto;gap:20px;align-items:center"><el-progress type="circle" :percentage="node?.progress||0" /><div><el-tag>{{node?.status}}</el-tag><el-tag v-if="node?.flags.overdue" type="danger" style="margin-left:8px">已延期</el-tag><el-tag v-if="node?.flags.blocked" type="warning" style="margin-left:8px">受阻</el-tag><p>{{node?.description||'暂无节点说明'}}</p><el-slider v-if="!readOnly" :model-value="node?.progress||0" :disabled="node?.status==='DONE'" @change="onProgress" /></div><div v-if="!readOnly" style="display:grid;gap:8px"><el-button v-if="node?.status==='NOT_STARTED'" type="primary" @click="setStatus('IN_PROGRESS')">开始节点</el-button><el-button v-if="node?.status==='IN_PROGRESS'" type="success" @click="setStatus('DONE')">完成节点</el-button><el-button v-if="node?.flags.blocked" @click="unblock">解除受阻</el-button><el-button v-else type="warning" plain @click="block">标记受阻</el-button></div></div></section>
<section class="surface"><div style="display:flex;justify-content:space-between"><h2>任务</h2><el-button v-if="!readOnly" type="primary" plain @click="taskDialog=true">新增任务</el-button></div><el-table :data="node?.tasks||[]"><el-table-column prop="name" label="任务" min-width="180"/><el-table-column prop="assigneeName" label="执行人"/><el-table-column prop="status" label="状态"/><el-table-column prop="estimateDays" label="计划人天"/><el-table-column prop="actualDays" label="实际人天"/><el-table-column prop="dueDate" label="截止日"/><el-table-column label="操作"><template #default="scope"><el-button v-if="!readOnly" link type="primary" @click="openWork(scope.row)">录工时</el-button></template></el-table-column></el-table></section>
<el-dialog v-model="taskDialog" title="新增任务"><el-form label-position="top"><el-form-item label="任务名称"><el-input v-model="taskForm.name"/></el-form-item><el-form-item label="描述"><el-input v-model="taskForm.description" type="textarea"/></el-form-item><el-form-item label="截止日期"><el-date-picker v-model="taskForm.dueDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="计划人天"><el-input-number v-model="taskForm.estimateDays" :step="0.5" :min="0"/></el-form-item></el-form><template #footer><el-button @click="taskDialog=false">取消</el-button><el-button type="primary" @click="createTask">创建</el-button></template></el-dialog>
<el-dialog v-model="workDialog" title="录入逐日工时"><el-form label-position="top"><el-form-item label="日期"><el-date-picker v-model="workForm.workDate" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="人天"><el-input-number v-model="workForm.days" :step="0.1" :min="0.1"/></el-form-item><el-form-item label="说明"><el-input v-model="workForm.note"/></el-form-item></el-form><template #footer><el-button @click="workDialog=false">取消</el-button><el-button type="primary" @click="addWork">保存</el-button></template></el-dialog></div></template>
